SELECT DISTINCTROW [Analisi materie prime].[Record numero], [Analisi materie prime].[Denominazione Commerciale], [Analisi materie prime].Provenienza, [Analisi materie prime].[Data di arrivo], [Analisi materie prime].[Analisi produttore], [Analisi materie prime].[Numero d'invio], [Analisi materie prime].[Targa Cisterna], [Analisi materie prime].[Numero di lotto], [Analisi materie prime].Sacchi, [Analisi materie prime].[Particelle ferromagnetiche], [Analisi materie prime].Vagliatura, [Analisi materie prime].[Contaminanti scuri], [Analisi materie prime].[Controllo SN], [Analisi materie prime].[Controllo DOP], [Analisi materie prime].[Controllo OSE], [Analisi materie prime].[Analisi 1], [Analisi materie prime].[Analisi 2], [Analisi materie prime].Note, [Analisi materie prime].[Destinazione Silo]
FROM [Analisi materie prime]
WHERE (([Analisi materie prime].[Destinazione Silo] Like [Inserire il Silo di destinazione]))
ORDER BY [Analisi materie prime].[Data di arrivo];
